import SwiftUI
import UserNotifications

class NotificationManager: NSObject, ObservableObject {
    static let shared = NotificationManager()

    @Published var permissionStatus: UNAuthorizationStatus = .notDetermined
    @AppStorage("notificationPermissionAsked") private var permissionAsked = false
    @AppStorage("notificationPermissionGranted") private var permissionGranted = false
    @AppStorage("lastScheduledMilestone") private var lastScheduledMilestone = 0
    @AppStorage("lastCheckInDate") private var lastCheckInDate = ""

    // Notification settings
    @AppStorage("dailyCheckInEnabled") private var dailyCheckInEnabled = true
    @AppStorage("motivationalQuotesEnabled") private var motivationalQuotesEnabled = true
    @AppStorage("milestoneRemindersEnabled") private var milestoneRemindersEnabled = true
    @AppStorage("cravingTipsEnabled") private var cravingTipsEnabled = false
    @AppStorage("checkInTime") private var checkInTimeString = "20:00"

    private override init() {
        super.init()
        checkPermissionStatus()
    }

    // MARK: - Permission Management

    func checkPermissionStatus() {
        UNUserNotificationCenter.current().getNotificationSettings { settings in
            DispatchQueue.main.async {
                self.permissionStatus = settings.authorizationStatus
                self.permissionGranted = settings.authorizationStatus == .authorized
            }
        }
    }

    func requestPermission() async -> Bool {
        do {
            let granted = try await UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .badge, .sound])

            await MainActor.run {
                self.permissionAsked = true
                self.permissionGranted = granted
                self.checkPermissionStatus()
            }

            if granted {
                await scheduleInitialNotifications()
            }

            return granted
        } catch {
            print("Error requesting notification permission: \(error)")
            return false
        }
    }

    // MARK: - Scheduling

    func scheduleInitialNotifications() async {
        // Remove all pending notifications first
        UNUserNotificationCenter.current().removeAllPendingNotificationRequests()

        // Schedule based on user preferences
        if dailyCheckInEnabled {
            scheduleDailyCheckIn()
        }

        if milestoneRemindersEnabled {
            await scheduleMilestoneNotifications()
        }

        if motivationalQuotesEnabled {
            scheduleMotivationalQuotes()
        }

        if cravingTipsEnabled {
            scheduleCravingSupport()
        }
    }

